  if (bytes.length === 0) return [new Uint8Array(0)];
  const out = [];
  for (let i = 0; i < bytes.length; i += maxPayload) {
    out.push(bytes.slice(i, Math.min(i + maxPayload, bytes.length)));
  }
  return out;
