      this.parts.push(decodeUtf8(f.payload));
    } catch (e) {
      if (!(e instanceof TypeError)) throw e;
      this.parts.push(null);
    }
    if (f.more) return;
    const parts = this.parts;
    this.parts = [];
    if (parts.includes(null)) {
      this.stats.invalid++;
      return;
    }
    this.stats.delivered++;
    delivered.push(parts.join(''));
  }
